    private void tblTransactionsMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_tblTransactionsMouseClicked
        int row = tblTransactions.getSelectedRow();
            if (row >= 0) {
                String date = String.valueOf(tblTransactions.getValueAt(row, 0));
                String ref = String.valueOf(tblTransactions.getValueAt(row, 1));
                String particulars = String.valueOf(tblTransactions.getValueAt(row, 2));
                
                System.out.println("Selected transaction: " + date + " / " + ref + " / " + particulars);
                
            }
        // TODO add your handling code here:
    }//GEN-LAST:event_tblTransactionsMouseClicked

